export function getImage(id) {
  const meta = manifest[id]
  if (!meta) throw new Error(`Unknown image id: ${id}`)
  const { widths } = meta
  return {
    id,
    ...meta,
    alt: alts[id] ?? '',
    src: `/images/${id}-${widths[Math.min(1, widths.length - 1)]}.webp`,
    largest: `/images/${id}-${widths[widths.length - 1]}.webp`,
    srcSet: widths.map((w) => `/images/${id}-${w}.webp ${w}w`).join(', '),
    attribution: `${meta.author} / ${meta.source}, ${meta.license}`,
  }
}

export const allImages = Object.keys(manifest).map(getImage)
